function App(){
 const [session,setSession]=React.useState<any>(null); const [profile,setProfile]=React.useState<Profile|null>(null); const [roles,setRoles]=React.useState<string[]>([]); const [permissions,setPermissions]=React.useState<string[]>([]);
 const [recoveryMode,setRecoveryMode]=React.useState(false); const [page,setPage]=React.useState<Page>('dashboard'); const [selectedDocId,setSelectedDocId]=React.useState<string|null>(null); const [error,setError]=React.useState(''); const [loading,setLoading]=React.useState(true);
 async function loadIdentity(user:User){const [p,r,pm]=await Promise.all([supabase.from('profiles').select('id,full_name,email,employee_code,department_id').eq('id',user.id).maybeSingle(),supabase.from('user_roles').select('roles(name,code)').eq('user_id',user.id),supabase.rpc('get_my_permissions')]);if(p.error)setError(p.error.message);else setProfile(p.data as Profile|null);if(!r.error)setRoles((r.data||[]).map((x:any)=>x.roles?.name||x.roles?.code).filter(Boolean));if(!pm.error)setPermissions((pm.data||[]).map((x:any)=>x.permission_code).filter(Boolean));}
 React.useEffect(()=>{let mounted=true;let released=false;const release=()=>{if(!released&&mounted){released=true;setLoading(false);}};const timer=window.setTimeout(release,1500);supabase.auth.getSession().then(async({data,error:sessionError})=>{if(!mounted)return;if(sessionError){setError('ไม่สามารถตรวจสอบสถานะการเข้าสู่ระบบได้ กรุณาลองใหม่');release();return;}setSession(data.session);if(data.session)await loadIdentity(data.session.user);release();}).catch(()=>{if(mounted){setError('ไม่สามารถเชื่อมต่อระบบยืนยันตัวตนได้ กรุณาลองใหม่');release();}});const {data}=supabase.auth.onAuthStateChange(async(event,s)=>{if(!mounted)return;if(event==='PASSWORD_RECOVERY')setRecoveryMode(true);setSession(s);if(s)await loadIdentity(s.user);else{setProfile(null);setRoles([]);setPermissions([]);}});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});return()=>{mounted=false;window.clearTimeout(timer);data.subscription.unsubscribe();};},[]);
 if(loading)return <div className="loading">กำลังโหลดระบบ…</div>; if(recoveryMode)return <ResetPassword onError={setError} onDone={()=>setRecoveryMode(false)}/>; if(!session)return <Login onError={setError} error={error}/>;
 return <Shell page={page} setPage={setPage} profile={profile} roles={roles} permissions={permissions} error={error} setError={setError} selectedDocId={selectedDocId} setSelectedDocId={setSelectedDocId} onSignOut={()=>supabase.auth.signOut()}/>;
}
function Login({error,onError}:{error:string;onError:(v:string)=>void}){const[email,setEmail]=React.useState('');const[password,setPassword]=React.useState('');const[busy,setBusy]=React.useState(false);const[notice,setNotice]=React.useState('');async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);onError('');setNotice('');const{error}=await supabase.auth.signInWithPassword({email,password});if(error)onError('อีเมลหรือรหัสผ่านไม่ถูกต้อง');setBusy(false);}async function forgot(){if(!email.trim()){onError('กรุณากรอกอีเมลก่อนกดลืมรหัสผ่าน');return}setBusy(true);onError('');setNotice('');const{error}=await supabase.auth.resetPasswordForEmail(email.trim(),{redirectTo:window.location.origin+'/'});if(error)onError('ส่งคำขอรีเซ็ตรหัสผ่านไม่สำเร็จ กรุณาลองใหม่');else setNotice('หากอีเมลนี้ลงทะเบียนในระบบ จะได้รับลิงก์สำหรับตั้งรหัสผ่านใหม่ โปรดตรวจสอบกล่องจดหมายและ Spam');setBusy(false);}return <main className="login"><section className="card login-card"><div className="brand">WBNS</div><h1>ระบบสารบรรณอิเล็กทรอนิกส์</h1><p>โรงเรียนวัดบึงน้ำใส</p><form onSubmit={submit}><label>อีเมล<input value={email}onChange={e=>setEmail(e.target.value)}type="email"required autoComplete="username"/></label><label>รหัสผ่าน<input value={password}onChange={e=>setPassword(e.target.value)}type="password"required autoComplete="current-password"/></label>{error&&<div className="error">{error}</div>}{notice&&<div className="success">{notice}</div>}<button disabled={busy}>{busy?'กำลังดำเนินการ…':'เข้าสู่ระบบ'}</button><button type="button" className="link-btn" disabled={busy} onClick={forgot}>ลืมรหัสผ่าน?</button></form></section></main>}
function ResetPassword({onError,onDone}:{onError:(v:string)=>void;onDone:()=>void}){const[password,setPassword]=React.useState('');const[confirm,setConfirm]=React.useState('');const[busy,setBusy]=React.useState(false);const[notice,setNotice]=React.useState('');async function submit(e:React.FormEvent){e.preventDefault();onError('');setNotice('');if(password.length<8){onError('รหัสผ่านต้องมีอย่างน้อย 8 ตัวอักษร');return}if(password!==confirm){onError('รหัสผ่านทั้งสองช่องไม่ตรงกัน');return}setBusy(true);const{error}=await supabase.auth.updateUser({password});if(error)onError('ตั้งรหัสผ่านใหม่ไม่สำเร็จ กรุณาขอลิงก์ใหม่');else{setNotice('ตั้งรหัสผ่านใหม่สำเร็จ กำลังกลับไปหน้าเข้าสู่ระบบ…');await supabase.auth.signOut();onDone()}setBusy(false);}return <main className="login"><section className="card login-card"><div className="brand">WBNS</div><h1>ตั้งรหัสผ่านใหม่</h1><p>โรงเรียนวัดบึงน้ำใส</p><form onSubmit={submit}><label>รหัสผ่านใหม่<input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength={8} required autoComplete="new-password"/></label><label>ยืนยันรหัสผ่านใหม่<input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} minLength={8} required autoComplete="new-password"/></label>{notice&&<div className="success">{notice}</div>}<button disabled={busy}>{busy?'กำลังบันทึก…':'บันทึกรหัสผ่านใหม่'}</button></form></section></main>}
function Shell({page,setPage,profile,roles,permissions,error,setError,selectedDocId,setSelectedDocId,onSignOut}:{page:Page;setPage:(p:Page)=>void;profile:Profile|null;roles:string[];permissions:string[];error:string;setError:(v:string)=>void;selectedDocId:string|null;setSelectedDocId:(v:string|null)=>void;onSignOut:()=>void}){const[mobile,setMobile]=React.useState(false);return <div className="shell"><aside className={mobile?'open':''}><div className="side-brand"><div className="brand small">WBNS</div><div><b>WBNS e-Document</b><small>โรงเรียนวัดบึงน้ำใส</small></div></div><nav><Nav active={page==='dashboard'}onClick={()=>{setPage('dashboard');setMobile(false)}}>ภาพรวม</Nav>{permissions.includes('registry.incoming.manage')&&<Nav active={page==='incoming'}onClick={()=>{setPage('incoming');setMobile(false)}}>หนังสือรับ</Nav>}{permissions.includes('registry.outgoing.manage')&&<Nav active={page==='outgoing'}onClick={()=>{setPage('outgoing');setMobile(false)}}>หนังสือส่ง</Nav>}<Nav active={page==='tasks'}onClick={()=>{setPage('tasks');setMobile(false)}}>งานของฉัน</Nav>{permissions.includes('document.approve')&&<Nav active={page==='approvals'}onClick={()=>{setPage('approvals');setMobile(false)}}>รออนุมัติ</Nav>}{permissions.includes('report.view')&&<Nav active={page==='reports'}onClick={()=>{setPage('reports');setMobile(false)}}>รายงาน</Nav>}<Nav active={page==='senders'}onClick={()=>{setPage('senders');setMobile(false)}}>หน่วยงานผู้ส่ง</Nav>{permissions.includes('audit.view')&&<Nav active={page==='audit'}onClick={()=>{setPage('audit');setMobile(false)}}>ประวัติการใช้งาน</Nav>}{(permissions.includes('user.manage')||permissions.includes('role.manage'))&&<><Nav active={page==='admin'}onClick={()=>{setPage('admin');setMobile(false)}}>ผู้ใช้และสิทธิ์</Nav><Nav active={page==='departments'}onClick={()=>{setPage('departments');setMobile(false)}}>หน่วยงานบุคลากร</Nav></>}</nav><div className="side-user"><b>{profile?.full_name||'ผู้ใช้งาน'}</b><span>{roles.join(' · ')||'ยังไม่ได้กำหนดบทบาท'}</span><button className="link-btn"onClick={onSignOut}>ออกจากระบบ</button></div></aside>{mobile&&<div className="backdrop"onClick={()=>setMobile(false)}/>}<main className="main"><header className="topbar"><button className="menu"onClick={()=>setMobile(!mobile)}>☰</button><div><b>{pageTitle(page)}</b><span>ระบบสารบรรณอิเล็กทรอนิกส์ โรงเรียนวัดบึงน้ำใส</span></div><div className="top-actions"><NotificationBell profile={profile} setError={setError}/><div className="user-chip">{profile?.full_name||'ผู้ใช้งาน'}</div></div></header>{error&&<div className="global-error">{error}<button onClick={()=>setError('')}>×</button></div>}<section className="page"><PageContent page={page} profile={profile} permissions={permissions} setError={setError} selectedDocId={selectedDocId} setSelectedDocId={setSelectedDocId}/></section></main></div>}
function urlBase64ToUint8Array(base64:string){const padding='='.repeat((4-base64.length%4)%4);const raw=atob((base64+padding).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from([...raw].map(x=>x.charCodeAt(0)))}
async function enablePush(profile:Profile|null){if(!profile)throw new Error('profile_required');if(!('serviceWorker'in navigator)||!('PushManager'in window))throw new Error('push_not_supported');const key=(import.meta.env.VITE_VAPID_PUBLIC_KEY as string|undefined)||'';if(!key)throw new Error('vapid_public_key_missing');const registration=await navigator.serviceWorker.ready;let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(key)});const json=subscription.toJSON();if(!json.endpoint||!json.keys?.p256dh||!json.keys?.auth)throw new Error('push_subscription_invalid');const{error}=await supabase.from('push_subscriptions').upsert({user_id:profile.id,endpoint:json.endpoint,p256dh:json.keys.p256dh,auth:json.keys.auth,user_agent:navigator.userAgent,revoked_at:null},{onConflict:'endpoint'});if(error)throw error;return true}
function NotificationBell({profile,setError}:{profile:Profile|null;setError:(v:string)=>void}){const[open,setOpen]=React.useState(false);const[rows,setRows]=React.useState<any[]>([]);const[pushReady,setPushReady]=React.useState(false);const[pushBusy,setPushBusy]=React.useState(false);async function load(){if(!profile)return;const{data,error}=await supabase.from('notifications').select('id,title,body,priority,created_at,read_at,document_id').eq('recipient_id',profile.id).order('created_at',{ascending:false}).limit(8);if(error)setError(error.message);else setRows(data||[])}React.useEffect(()=>{load();setPushReady(!!('serviceWorker'in navigator&&'PushManager'in window))},[profile?.id]);const unread=rows.filter(x=>!x.read_at).length;async function mark(id:string){await supabase.from('notifications').update({read_at:new Date().toISOString()}).eq('id',id).eq('recipient_id',profile?.id);setRows(rows.map(x=>x.id===id?{...x,read_at:new Date().toISOString()}:x))}async function activatePush(){setPushBusy(true);setError('');try{await enablePush(profile);setError('');alert('เปิดการแจ้งเตือนบนอุปกรณ์นี้แล้ว')}catch(e:any){const code=e?.message||'push_enable_failed';setError(code==='vapid_public_key_missing'?'ยังไม่ได้ตั้งค่า VAPID Public Key สำหรับ Web Push':code==='push_not_supported'?'เบราว์เซอร์นี้ไม่รองรับ Web Push':'ไม่สามารถเปิดการแจ้งเตือนได้ กรุณาอนุญาตการแจ้งเตือนในเบราว์เซอร์')}finally{setPushBusy(false)}}return <div className="notification-wrap"><button className="bell"onClick={()=>{setOpen(!open);if(!open)load()}}>🔔{unread>0&&<i>{unread}</i>}</button>{open&&<div className="notification-pop"><div className="notification-head"><b>การแจ้งเตือน</b><button className="link-btn"onClick={async()=>{if(!profile)return;await supabase.from('notifications').update({read_at:new Date().toISOString()}).eq('recipient_id',profile.id).is('read_at',null);load()}}>อ่านทั้งหมด</button></div>{pushReady&&<div className="push-action"><button className="ghost"disabled={pushBusy}onClick={activatePush}>{pushBusy?'กำลังเปิด…':'เปิดการแจ้งเตือนบนอุปกรณ์นี้'}</button></div>}{rows.length===0?<div className="empty">ไม่มีการแจ้งเตือน</div>:rows.map(n=><button key={n.id}className={'notification '+(n.read_at?'':'unread')}onClick={()=>mark(n.id)}><b>{n.title}</b><span>{n.body}</span><small>{new Date(n.created_at).toLocaleString('th-TH')}</small></button>)}</div>}</div>}
function Nav({children,active,onClick}:{children:React.ReactNode;active:boolean;onClick:()=>void}){return <button className={active?'nav active':'nav'}onClick={onClick}>{children}</button>}
function pageTitle(p:Page){return({dashboard:'ภาพรวมระบบ',incoming:'ทะเบียนหนังสือรับ',outgoing:'ทะเบียนหนังสือส่ง',senders:'หน่วยงานผู้ส่ง',tasks:'งานของฉัน',approvals:'รายการรออนุมัติ',audit:'ประวัติการใช้งาน',reports:'รายงานและสถิติ',admin:'ผู้ใช้และสิทธิ์',departments:'หน่วยงานบุคลากร'}as any)[p]}
function PageContent({page,profile,permissions,setError,selectedDocId,setSelectedDocId}:{page:Page;profile:Profile|null;permissions:string[];setError:(v:string)=>void;selectedDocId:string|null;setSelectedDocId:(v:string|null)=>void}){if(selectedDocId)return <DocumentDetail documentId={selectedDocId} onBack={()=>setSelectedDocId(null)} setError={setError} permissions={permissions}/>;if(page==='incoming')return <Incoming setError={setError} openDocument={setSelectedDocId}/>;if(page==='outgoing')return <Outgoing setError={setError} openDocument={setSelectedDocId}/>;if(page==='reports')return <Reports/>;if(page==='senders')return <Senders setError={setError}/>;if(page==='tasks')return <Tasks profile={profile} openDocument={setSelectedDocId}/>;if(page==='approvals')return <Approvals profile={profile} setError={setError} openDocument={setSelectedDocId}/>;if(page==='audit')return <AuditLogs setError={setError}/>;if(page==='admin')return <AdminUsers setError={setError}/>;if(page==='departments')return <Departments setError={setError}/>;return <Dashboard profile={profile}/>}
function UserImport({onClose,setError,onDone}:{onClose:()=>void;setError:(v:string)=>void;onDone:()=>Promise<void>|void}){
 const[file,setFile]=React.useState<File|null>(null);const[rows,setRows]=React.useState<any[]>([]);const[roles,setRoles]=React.useState<any[]>([]);const[departments,setDepartments]=React.useState<any[]>([]);const[busy,setBusy]=React.useState(false);const[result,setResult]=React.useState<any>(null);
 const aliases:any={employee_code:['employee_code','รหัสบุคลากร','รหัสพนักงาน','รหัสครู'],full_name:['full_name','ชื่อ-นามสกุล','ชื่อสกุล','ชื่อ'],email:['email','อีเมล','อีเมล์'],phone:['phone','โทรศัพท์','เบอร์โทร'],department:['department','หน่วยงาน','ฝ่าย','กลุ่มงาน'],role:['role','บทบาท','สิทธิ์'],is_active:['is_active','สถานะ','สถานะการใช้งาน','ใช้งาน']};
 React.useEffect(()=>{(async()=>{const[r,d]=await Promise.all([supabase.from('roles').select('id,code,name').order('name'),supabase.from('departments').select('id,code,name,is_active').eq('is_active',true).order('code')]);if(r.error)setError(r.error.message);else setRoles(r.data||[]);if(d.error)setError(d.error.message);else setDepartments(d.data||[])})()},[]);const norm=(v:any)=>String(v??'').trim().toLowerCase().replace(/\\s+/g,'_');
 const findKey=(obj:any,names:string[])=>{const keys=Object.keys(obj);const hit=keys.find(k=>names.map(norm).includes(norm(k)));return hit?obj[hit]:''};
 const toActive=(v:any)=>{const x=String(v??'').trim().toLowerCase();return x===''||!['0','false','ไม่ใช้งาน','ปิด','inactive'].includes(x)};
 async function read(f:File){setFile(f);setError('');setResult(null);try{const wb=XLSX.read(await f.arrayBuffer(),{type:'array'});if(!wb.SheetNames.length)throw new Error('no_sheet');const ws=wb.Sheets[wb.SheetNames[0]];const raw=XLSX.utils.sheet_to_json<any>(ws,{defval:''});if(raw.length>200){setRows([]);setError('ไฟล์มีเกิน 200 รายการต่อครั้ง');return}const parsed=raw.map((r:any,i:number)=>({row:i+2,employee_code:String(findKey(r,aliases.employee_code)||'').trim(),full_name:String(findKey(r,aliases.full_name)||'').trim(),email:String(findKey(r,aliases.email)||'').trim().toLowerCase(),phone:String(findKey(r,aliases.phone)||'').trim(),department:String(findKey(r,aliases.department)||'').trim(),role:String(findKey(r,aliases.role)||'').trim(),is_active:toActive(findKey(r,aliases.is_active))}));setRows(parsed)}catch{setRows([]);setError('อ่านไฟล์ Excel ไม่สำเร็จ กรุณาใช้ไฟล์ .xlsx ที่ไม่เสียหาย')}} 
 const roleMap=React.useMemo(()=>{const m:any={};roles.forEach(r=>{m[r.code.toLowerCase()]=r;m[r.name.toLowerCase()]=r});return m},[roles]);const departmentMap=React.useMemo(()=>{const m:any={};departments.forEach(d=>{m[d.code.toLowerCase()]=d;m[d.name.toLowerCase()]=d});return m},[departments]);
 const checked=React.useMemo(()=>{const seenCode=new Set<string>(),seenEmail=new Set<string>();return rows.map(r=>{const errors:string[]=[];const code=r.employee_code.toLowerCase(),email=r.email.toLowerCase();if(!r.full_name)errors.push('ไม่มีชื่อ');if(!email||!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email))errors.push('อีเมลไม่ถูกต้อง');if(code&&seenCode.has(code))errors.push('รหัสบุคลากรซ้ำในไฟล์');if(email&&seenEmail.has(email))errors.push('อีเมลซ้ำในไฟล์');if(code)seenCode.add(code);if(email)seenEmail.add(email);if(r.role&&!roleMap[r.role.toLowerCase()])errors.push('ไม่พบ Role ในระบบ');if(!r.department)errors.push('ไม่มีหน่วยงาน');else if(!departmentMap[r.department.toLowerCase()])errors.push('ไม่พบหน่วยงานในระบบ');return {...r,roleRef:r.role?roleMap[r.role.toLowerCase()]:null,departmentRef:r.department?departmentMap[r.department.toLowerCase()]:null,errors}})},[rows,roleMap,departmentMap]);
 const counts={ready:checked.filter(x=>!x.errors.length).length,error:checked.filter(x=>x.errors.length).length};
 function downloadTemplate(){const data=[{'รหัสบุคลากร':'WBNS001','ชื่อ-นามสกุล':'ตัวอย่าง ผู้ใช้งาน','อีเมล':'example@school.ac.th','โทรศัพท์':'0812345678','หน่วยงาน':'ธุรการ','Role':'staff','สถานะการใช้งาน':'ใช้งาน'}];const ws=XLSX.utils.json_to_sheet(data);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Users');XLSX.writeFile(wb,'WBNS_User_Import_Template.xlsx')}
 function exportErrors(){const data=checked.filter(x=>x.errors.length).map(x=>({แถว:x.row,รหัสบุคลากร:x.employee_code,ชื่อ:x.full_name,อีเมล:x.email,หน่วยงาน:x.department,Role:x.role,ข้อผิดพลาด:x.errors.join(' / ')}));const ws=XLSX.utils.json_to_sheet(data);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'ข้อผิดพลาด');XLSX.writeFile(wb,'wbns-user-import-errors.xlsx')}
 async function importUsers(){const good=checked.filter(x=>!x.errors.length).map(({roleRef,departmentRef,...r})=>r);if(!good.length){setError('ไม่มีรายการที่ผ่านการตรวจสอบ');return}setBusy(true);setError('');setResult(null);const{data,error}=await supabase.functions.invoke('user-import',{body:{rows:good}});if(error){setError(error.message||'นำเข้าผู้ใช้ไม่สำเร็จ');setBusy(false);return}if(!data?.ok){setError(data?.code||'นำเข้าผู้ใช้ไม่สำเร็จ');setBusy(false);return}setResult(data);setBusy(false);await onDone()}
 return <Modal title="นำเข้าผู้ใช้จาก Excel" onClose={onClose}><div className="notice">รองรับสูงสุด 200 รายการต่อครั้ง · หน่วยงานต้องตรงกับหน่วยงานที่เปิดใช้งานในระบบ · Role ต้องตรงกับ Role ที่มีอยู่ · ระบบตรวจสอบข้อมูลก่อนส่งเข้า Server · หน่วยงานต้องเป็นรายการที่เปิดใช้งาน · ผู้ใช้ใหม่จะได้รับคำเชิญเข้าสู่ Supabase Auth ทางอีเมล · ไม่ต้องใส่รหัสผ่านใน Excel</div><div className="row-actions"><button type="button" className="ghost" onClick={downloadTemplate}>ดาวน์โหลด Template</button><label className="button-like">เลือกไฟล์ Excel<input type="file" accept=".xlsx,.xls" hidden onChange={e=>e.target.files?.[0]&&read(e.target.files[0])}/></label></div>{file&&<div className="muted">ไฟล์: {file.name} · {rows.length} แถว</div>}{rows.length>0&&<><div className="stats-grid"><div className="stat-card"><b>พร้อมนำเข้า</b><strong>{counts.ready}</strong></div><div className="stat-card"><b>ผิดพลาด</b><strong>{counts.error}</strong></div></div><div className="table-wrap"><table><thead><tr><th>แถว</th><th>บุคลากร</th><th>อีเมล</th><th>หน่วยงาน</th><th>Role</th><th>ตรวจสอบ</th></tr></thead><tbody>{checked.slice(0,100).map(x=><tr key={x.row}><td>{x.row}</td><td>{x.full_name||'—'}<small className="muted">{x.employee_code}</small></td><td>{x.email||'—'}</td><td>{x.department||'—'}{x.departmentRef&&<small className="muted">✓ {x.departmentRef.code} — {x.departmentRef.name}</small>}</td><td>{x.role||'—'}</td><td>{x.errors.length?<span className="badge">ผิดพลาด: {x.errors.join(' / ')}</span>:<span className="badge">พร้อม</span>}</td></tr>)}</tbody></table>{checked.length>100&&<div className="muted">แสดงตัวอย่าง 100 แถวแรก แต่ระบบตรวจสอบครบทุกแถว</div>}</div>{result&&<div className="notice">นำเข้าสำเร็จ: เชิญผู้ใช้ใหม่ {result.summary?.invited||0} · อัปเดตผู้ใช้เดิม {result.summary?.updated||0} · ผิดพลาด {result.summary?.errors||0}</div>}<div className="form-actions"><button type="button" className="ghost" onClick={exportErrors} disabled={!counts.error}>ส่งออกข้อผิดพลาด</button><button type="button" className="ghost" onClick={onClose}>ปิด</button><button type="button" disabled={busy||counts.ready===0} onClick={importUsers}>{busy?'กำลังนำเข้า…':'นำเข้าผู้ใช้ที่ผ่านการตรวจสอบ'}</button></div></>}</Modal>}

function AdminUsers({setError}:{setError:(v:string)=>void}){const[users,setUsers]=React.useState<any[]>([]);const[roles,setRoles]=React.useState<any[]>([]);const[departments,setDepartments]=React.useState<any[]>([]);const[q,setQ]=React.useState('');const[departmentFilter,setDepartmentFilter]=React.useState('');const[loading,setLoading]=React.useState(true);const[busy,setBusy]=React.useState<string|null>(null);const[importOpen,setImportOpen]=React.useState(false);async function load(){setLoading(true);const[u,r,d]=await Promise.all([supabase.from('profiles').select('id,full_name,email,employee_code,is_active,department_id,user_roles!user_roles_user_id_fkey(role_id,roles(id,code,name)),departments(id,code,name,is_active)').order('full_name'),supabase.from('roles').select('id,code,name').order('name'),supabase.from('departments').select('id,code,name,is_active').order('code')]);if(u.error)setError(u.error.message);else setUsers(u.data||[]);if(r.error)setError(r.error.message);else setRoles(r.data||[]);if(d.error)setError(d.error.message);else setDepartments(d.data||[]);setLoading(false)}React.useEffect(()=>{load()},[]);async function setRole(userId:string,roleId:string){if(!roleId)return;setBusy(userId);setError('');const{error}=await supabase.rpc('admin_set_user_role',{p_user_id:userId,p_role_id:roleId});if(error)setError(error.message);else await load();setBusy(null)}async function removeRole(userId:string,roleId:string){setBusy(userId);setError('');const{error}=await supabase.rpc('admin_remove_user_role',{p_user_id:userId,p_role_id:roleId});if(error)setError(error.message);else await load();setBusy(null)}async function setDepartment(userId:string,departmentId:string){setBusy(userId);setError('');const{error}=await supabase.rpc('admin_set_user_department',{p_user_id:userId,p_department_id:departmentId||null});if(error)setError(error.message);else await load();setBusy(null)}async function action(userId:string,kind:'set_active'|'resend_invitation',active?:boolean){setBusy(userId);setError('');const{data,error}=await supabase.functions.invoke('user-import',{body:{action:kind,user_id:userId,is_active:active}});if(error||!data?.ok)setError(data?.code||error?.message||'ดำเนินการไม่สำเร็จ');else await load();setBusy(null)}const filteredUsers=users.filter(u=>{const text=[u.full_name,u.email,u.employee_code].filter(Boolean).join(' ').toLowerCase();return (!q||text.includes(q.toLowerCase()))&&(!departmentFilter||u.department_id===departmentFilter)});return <div><div className="toolbar"><div><h1>จัดการผู้ใช้งานและสิทธิ์</h1><p>กำหนดหน่วยงาน Role สถานะบัญชี และนำเข้ารายชื่อจาก Excel</p></div><div className="row-actions"><button className="ghost" onClick={()=>setImportOpen(true)}>นำเข้า Excel</button><button className="ghost"onClick={load}>รีเฟรช</button></div></div><div className="panel"><div className="filter-bar"><input placeholder="ค้นหาชื่อ / อีเมล / รหัสบุคลากร…" value={q} onChange={e=>setQ(e.target.value)}/><select value={departmentFilter} onChange={e=>setDepartmentFilter(e.target.value)}><option value="">ทุกหน่วยงาน</option>{departments.filter(d=>d.is_active).map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></div><div className="notice">บัญชีใหม่ถูกเชิญผ่าน Server เท่านั้น · เปลี่ยนหน่วยงานและ Role จากหน้านี้ได้ทันที · หน่วยงานที่เลือกต้องเปิดใช้งาน · ปิดใช้งานจะตัดสิทธิ์การใช้งานจาก Profile</div>{loading?<div className="empty">กำลังโหลด…</div>:<div className="table-wrap"><table><thead><tr><th>บุคลากร</th><th>อีเมล</th><th>หน่วยงาน</th><th>สถานะ</th><th>Role ปัจจุบัน</th><th>เพิ่ม Role</th><th>การจัดการ</th></tr></thead><tbody>{filteredUsers.map(u=><tr key={u.id}><td><b>{u.full_name||'—'}</b><small className="muted">{u.employee_code||''}</small></td><td>{u.email||'—'}</td><td><select disabled={busy===u.id}value={u.department_id||''}onChange={e=>setDepartment(u.id,e.target.value)}><option value="">ไม่ระบุหน่วยงาน</option>{departments.filter(d=>d.is_active).map(d=><option key={d.id}value={d.id}>{d.name} ({d.code})</option>)}</select></td><td><span className="badge">{u.is_active?'ใช้งาน':'ปิดใช้งาน'}</span></td><td>{(u.user_roles||[]).map((ur:any)=><span className="badge"key={ur.role_id}>{ur.roles?.name||ur.roles?.code}<button className="icon-btn"disabled={busy===u.id}onClick={()=>removeRole(u.id,ur.role_id)}>×</button></span>)}</td><td><select disabled={busy===u.id}defaultValue=""onChange={e=>setRole(u.id,e.target.value)}><option value="">เลือก Role</option>{roles.map(r=><option key={r.id}value={r.id}>{r.name} ({r.code})</option>)}</select></td><td><div className="row-actions"><button className="ghost"disabled={busy===u.id}onClick={()=>action(u.id,'set_active',!u.is_active)}>{u.is_active?'ปิดใช้งาน':'เปิดใช้งาน'}</button><button className="ghost"disabled={busy===u.id||!u.email}onClick={()=>action(u.id,'resend_invitation')}>ส่งคำเชิญใหม่</button></div></td></tr>)}</tbody></table>{filteredUsers.length===0&&<div className="empty">ไม่พบผู้ใช้งานตามเงื่อนไข</div>}</div>}</div>{importOpen&&<UserImport onClose={()=>setImportOpen(false)} setError={setError} onDone={load}/>}</div>}
function Departments({setError}:{setError:(v:string)=>void}){const[rows,setRows]=React.useState<any[]>([]);const[loading,setLoading]=React.useState(true);const[busy,setBusy]=React.useState(false);const[open,setOpen]=React.useState(false);const[editing,setEditing]=React.useState<any>(null);const[form,setForm]=React.useState({code:'',name:'',parent_id:'',is_active:true});async function load(){setLoading(true);const{data,error}=await supabase.from('departments').select('id,code,name,parent_id,is_active,created_at,updated_at').order('code');if(error)setError(error.message);else setRows(data||[]);setLoading(false)}React.useEffect(()=>{load()},[]);function startCreate(){setEditing(null);setForm({code:'',name:'',parent_id:'',is_active:true});setOpen(true)}function startEdit(r:any){setEditing(r);setForm({code:r.code||'',name:r.name||'',parent_id:r.parent_id||'',is_active:r.is_active!==false});setOpen(true)}async function save(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');const payload={p_code:form.code,p_name:form.name,p_parent_id:form.parent_id||null,p_is_active:form.is_active};const{error}=editing?await supabase.rpc('admin_update_department',{p_department_id:editing.id,...payload}):await supabase.rpc('admin_create_department',{p_code:form.code,p_name:form.name,p_parent_id:form.parent_id||null});if(error)setError(error.message);else{setOpen(false);await load()}setBusy(false)}async function toggle(r:any){setBusy(true);setError('');const{error}=await supabase.rpc('admin_update_department',{p_department_id:r.id,p_code:r.code,p_name:r.name,p_parent_id:r.parent_id||null,p_is_active:!r.is_active});if(error)setError(error.message);else await load();setBusy(false)}const byId:any=React.useMemo(()=>Object.fromEntries(rows.map(r=>[r.id,r])),[rows]);return <div><div className="toolbar"><div><h1>จัดการหน่วยงานบุคลากร</h1><p>กำหนดหน่วยงานสำหรับ Profile และใช้เป็นข้อมูลอ้างอิงในการนำเข้า Excel</p></div><div className="row-actions"><button onClick={startCreate}>+ เพิ่มหน่วยงาน</button><button className="ghost"onClick={load}>รีเฟรช</button></div></div><div className="panel"><div className="notice">ใช้รหัสหน่วยงานที่ไม่ซ้ำกัน และปิดใช้งานแทนการลบ เพื่อไม่ให้ประวัติบุคลากรเดิมเสียความสัมพันธ์</div>{loading?<div className="empty">กำลังโหลด…</div>:<div className="table-wrap"><table><thead><tr><th>รหัส</th><th>ชื่อหน่วยงาน</th><th>หน่วยงานแม่</th><th>สถานะ</th><th>การจัดการ</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td className="mono">{r.code}</td><td><b>{r.name}</b></td><td>{r.parent_id?byId[r.parent_id]?.name||'—':'—'}</td><td><span className="badge">{r.is_active?'ใช้งาน':'ปิดใช้งาน'}</span></td><td><div className="row-actions"><button className="ghost"disabled={busy}onClick={()=>startEdit(r)}>แก้ไข</button><button className="ghost"disabled={busy}onClick={()=>toggle(r)}>{r.is_active?'ปิดใช้งาน':'เปิดใช้งาน'}</button></div></td></tr>)}</tbody></table>{rows.length===0&&<div className="empty">ยังไม่มีหน่วยงาน</div>}</div>}</div>{open&&<Modal title={editing?'แก้ไขหน่วยงาน':'เพิ่มหน่วยงาน'}onClose={()=>setOpen(false)}><form className="form-grid"onSubmit={save}><label>รหัสหน่วยงาน<input required value={form.code}onChange={e=>setForm({...form,code:e.target.value})}placeholder="เช่น ADMIN"/></label><label>ชื่อหน่วยงาน<input required value={form.name}onChange={e=>setForm({...form,name:e.target.value})}placeholder="เช่น งานธุรการ"/></label><label className="wide">หน่วยงานแม่<select value={form.parent_id}onChange={e=>setForm({...form,parent_id:e.target.value})}><option value="">ไม่มี</option>{rows.filter(r=>r.id!==editing?.id&&r.is_active).map(r=><option key={r.id}value={r.id}>{r.code} — {r.name}</option>)}</select></label>{editing&&<label className="wide"><span><input type="checkbox"checked={form.is_active}onChange={e=>setForm({...form,is_active:e.target.checked})}/> ใช้งานหน่วยงานนี้</span></label>}<div className="form-actions"><button type="button"className="ghost"onClick={()=>setOpen(false)}>ยกเลิก</button><button disabled={busy}>{busy?'กำลังบันทึก…':'บันทึก'}</button></div></form></Modal>}</div>}

function Dashboard({profile}:{profile:Profile|null}){const[docs,setDocs]=React.useState<Doc[]>([]);const[counts,setCounts]=React.useState({incoming:0,outgoing:0,tasks:0,urgent:0});const[loading,setLoading]=React.useState(true);async function load(){setLoading(true);const[d,i,o,t,u]=await Promise.all([supabase.from('documents').select('id,subject,urgency,status,created_at,document_type').order('created_at',{ascending:false}).limit(8),supabase.from('documents').select('id',{count:'exact',head:true}).eq('document_type','incoming'),supabase.from('documents').select('id',{count:'exact',head:true}).eq('document_type','outgoing'),profile?supabase.from('document_assignments').select('id',{count:'exact',head:true}).eq('assignee_id',profile.id).in('assignment_status',['assigned','accepted','in_progress']):Promise.resolve({count:0}),supabase.from('documents').select('id',{count:'exact',head:true}).in('urgency',['urgent','very_urgent','critical']).not('status','in','(completed,archived,cancelled)')]);setDocs((d.data||[])as Doc[]);setCounts({incoming:i.count||0,outgoing:o.count||0,tasks:t.count||0,urgent:u.count||0});setLoading(false)}React.useEffect(()=>{load()},[profile?.id]);return <div><div className="welcome"><h1>สวัสดี {profile?.full_name||'ผู้ใช้งาน'}</h1><p>ศูนย์กลางติดตามงานสารบรรณของโรงเรียน</p></div><div className="stat-grid"><Stat label="หนังสือรับ"value={counts.incoming}/><Stat label="หนังสือส่ง"value={counts.outgoing}/><Stat label="งานของฉัน"value={counts.tasks}/><Stat label="เรื่องเร่งด่วน"value={counts.urgent}danger/></div><div className="panel"><div className="panel-head"><div><h2>เอกสารล่าสุด</h2><p>รายการล่าสุดที่ผู้ใช้งานมีสิทธิ์เข้าถึง</p></div><button className="ghost"onClick={load}>รีเฟรช</button></div>{loading?<div className="empty">กำลังโหลด…</div>:docs.length===0?<div className="empty">ยังไม่มีเอกสารในระบบ หรือบัญชีนี้ยังไม่มีสิทธิ์เข้าถึงเอกสาร</div>:<div className="table-wrap"><table><thead><tr><th>ประเภท</th><th>เรื่อง</th><th>ความเร่งด่วน</th><th>สถานะ</th><th>วันที่</th></tr></thead><tbody>{docs.map(d=><tr key={d.id}><td>{d.document_type==='incoming'?'หนังสือรับ':'หนังสือส่ง'}</td><td><span className="subject-link">{d.subject}</span></td><td><span className={'badge urgency '+d.urgency}>{urgencyLabel[d.urgency]}</span></td><td><span className="badge">{statusLabel[d.status]||d.status}</span></td><td>{new Date(d.created_at).toLocaleDateString('th-TH')}</td></tr>)}</tbody></table></div>}</div></div>}
function Stat({label,value,danger=false}:{label:string;value:number;danger?:boolean}){return <article className={'stat '+(danger?'danger':'')}><span>{label}</span><strong>{value}</strong></article>}
function Incoming({setError,openDocument}:{setError:(v:string)=>void;openDocument:(id:string)=>void}){const[senders,setSenders]=React.useState<Sender[]>([]);const[docs,setDocs]=React.useState<Doc[]>([]);const[q,setQ]=React.useState('');const[status,setStatus]=React.useState('');const[urgency,setUrgency]=React.useState('');const[open,setOpen]=React.useState(false);const[busy,setBusy]=React.useState(false);const[form,setForm]=React.useState({subject:'',sender_id:'',external_document_no:'',external_document_date:'',received_at:new Date().toISOString().slice(0,16),urgency:'normal',receiving_notes:''});async function load(){let dQuery=supabase.from('documents').select('id,subject,urgency,status,created_at,document_type,incoming_document_details(registered_number,external_document_no,received_at,sender_id)').eq('document_type','incoming');if(q)dQuery=dQuery.ilike('subject',`%${q}%`);if(urgency)dQuery=dQuery.eq('urgency',urgency);if(status)dQuery=dQuery.eq('status',status);dQuery=dQuery.order('created_at',{ascending:false}).limit(100);const[s,d]=await Promise.all([supabase.from('senders').select('id,organization_name,department_name').eq('is_active',true).order('organization_name'),dQuery]);if(s.error)setError(s.error.message);else setSenders(s.data||[]);if(d.error)setError(d.error.message);else setDocs(d.data as Doc[]||[])}React.useEffect(()=>{load()},[q,status,urgency]);async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');const{error}=await supabase.rpc('register_incoming_document',{p_subject:form.subject,p_sender_id:form.sender_id,p_external_document_no:form.external_document_no||null,p_external_document_date:form.external_document_date||null,p_received_at:new Date(form.received_at).toISOString(),p_urgency:form.urgency,p_receiving_notes:form.receiving_notes||null});if(error)setError(error.message);else{setOpen(false);setForm({...form,subject:'',sender_id:'',external_document_no:'',external_document_date:'',receiving_notes:''});await load()}setBusy(false)}return <div><div className="toolbar"><div><h1>ทะเบียนหนังสือรับ</h1><p>รับเรื่อง ลงทะเบียน และติดตามหนังสือจากหน่วยงานภายนอก</p></div><button onClick={()=>setOpen(true)}>+ รับหนังสือ</button></div><div className="panel"><div className="filter-bar"><input placeholder="ค้นหาเรื่อง…" value={q} onChange={e=>setQ(e.target.value)}/><select value={urgency} onChange={e=>setUrgency(e.target.value)}><option value="">ทุกความเร่งด่วน</option>{Object.entries(urgencyLabel).map(([v,l])=><option key={v} value={v}>{String(l)}</option>)}</select><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">ทุกสถานะ</option>{Object.entries(statusLabel).map(([v,l])=><option key={v} value={v}>{String(l)}</option>)}</select></div><div className="table-wrap"><table><thead><tr><th>เลขทะเบียน</th><th>เรื่อง</th><th>เลขที่จากผู้ส่ง</th><th>ความเร่งด่วน</th><th>สถานะ</th><th>รับเมื่อ</th></tr></thead><tbody>{docs.map(d=>{const x=d.incoming_document_details?.[0];return <tr key={d.id}><td>{x?.registered_number||'—'}</td><td><button className="subject-link" onClick={()=>openDocument(d.id)}>{d.subject}</button></td><td>{x?.external_document_no||'—'}</td><td><span className={'badge urgency '+d.urgency}>{urgencyLabel[d.urgency]}</span></td><td><span className="badge">{statusLabel[d.status]}</span></td><td>{x?.received_at?new Date(x.received_at).toLocaleString('th-TH'):'—'}</td></tr>})}</tbody></table>{docs.length===0&&<div className="empty">ยังไม่มีหนังสือรับ</div>}</div></div>{open&&<Modal title="ลงทะเบียนหนังสือรับ"onClose={()=>setOpen(false)}><form className="form-grid"onSubmit={submit}><label className="wide">เรื่อง<input required value={form.subject}onChange={e=>setForm({...form,subject:e.target.value})}/></label><label>หน่วยงานผู้ส่ง<select required value={form.sender_id}onChange={e=>setForm({...form,sender_id:e.target.value})}><option value="">เลือกหน่วยงาน</option>{senders.map(s=><option key={s.id}value={s.id}>{s.organization_name}{s.department_name?' — '+s.department_name:''}</option>)}</select></label><label>เลขที่หนังสือจากผู้ส่ง<input value={form.external_document_no}onChange={e=>setForm({...form,external_document_no:e.target.value})}/></label><label>วันที่หนังสือ<input type="date"value={form.external_document_date}onChange={e=>setForm({...form,external_document_date:e.target.value})}/></label><label>รับเมื่อ<input type="datetime-local"value={form.received_at}onChange={e=>setForm({...form,received_at:e.target.value})}/></label><label>ความเร่งด่วน<select value={form.urgency}onChange={e=>setForm({...form,urgency:e.target.value})}>{Object.entries(urgencyLabel).map(([v,l])=><option key={v} value={v}>{String(l)}</option>)}</select></label><label className="wide">หมายเหตุ<textarea value={form.receiving_notes}onChange={e=>setForm({...form,receiving_notes:e.target.value})}/></label><div className="form-actions"><button type="button"className="ghost"onClick={()=>setOpen(false)}>ยกเลิก</button><button disabled={busy}>{busy?'กำลังบันทึก…':'บันทึกและออกเลขทะเบียน'}</button></div></form></Modal>}</div>}
function Outgoing({setError,openDocument}:{setError:(v:string)=>void;openDocument:(id:string)=>void}){const[docs,setDocs]=React.useState<Doc[]>([]);const[q,setQ]=React.useState('');const[status,setStatus]=React.useState('');const[urgency,setUrgency]=React.useState('');const[open,setOpen]=React.useState(false);const[busy,setBusy]=React.useState(false);const[form,setForm]=React.useState({subject:'',recipient_name:'',recipient_address:'',recipient_contact:'',document_date:new Date().toISOString().slice(0,10),urgency:'normal'});async function load(){let dQuery=supabase.from('documents').select('id,subject,urgency,status,created_at,document_type,outgoing_document_details(registered_number,recipient_name,outgoing_document_no,document_date)').eq('document_type','outgoing');if(q)dQuery=dQuery.ilike('subject',`%${q}%`);if(urgency)dQuery=dQuery.eq('urgency',urgency);if(status)dQuery=dQuery.eq('status',status);const{data,error}=await dQuery.order('created_at',{ascending:false}).limit(100);if(error)setError(error.message);else setDocs(data as Doc[]||[])}React.useEffect(()=>{load()},[q,status,urgency]);async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);const{error}=await supabase.rpc('register_outgoing_document',{p_subject:form.subject,p_recipient_name:form.recipient_name,p_recipient_address:form.recipient_address||null,p_recipient_contact:form.recipient_contact||null,p_document_date:form.document_date,p_urgency:form.urgency});if(error)setError(error.message);else{setOpen(false);setForm({...form,subject:'',recipient_name:'',recipient_address:'',recipient_contact:''});await load()}setBusy(false)}return <div><div className="toolbar"><div><h1>ทะเบียนหนังสือส่ง</h1><p>สร้างหนังสือส่งและเตรียมเข้าสู่ขั้นตอนอนุมัติ</p></div><button onClick={()=>setOpen(true)}>+ สร้างหนังสือส่ง</button></div><div className="panel"><div className="filter-bar"><input placeholder="ค้นหาเรื่อง…" value={q} onChange={e=>setQ(e.target.value)}/><select value={urgency} onChange={e=>setUrgency(e.target.value)}><option value="">ทุกความเร่งด่วน</option>{Object.entries(urgencyLabel).map(([v,l])=><option key={v} value={v}>{String(l)}</option>)}</select><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">ทุกสถานะ</option>{Object.entries(statusLabel).map(([v,l])=><option key={v} value={v}>{String(l)}</option>)}</select></div><div className="table-wrap"><table><thead><tr><th>เลขทะเบียน</th><th>เรื่อง</th><th>ผู้รับ</th><th>ความเร่งด่วน</th><th>สถานะ</th><th>วันที่</th></tr></thead><tbody>{docs.map(d=>{const x=d.outgoing_document_details?.[0];return <tr key={d.id}><td>{x?.registered_number||'—'}</td><td><button className="subject-link" onClick={()=>openDocument(d.id)}>{d.subject}</button></td><td>{x?.recipient_name||'—'}</td><td><span className={'badge urgency '+d.urgency}>{urgencyLabel[d.urgency]}</span></td><td><span className="badge">{statusLabel[d.status]}</span></td><td>{x?.document_date?new Date(x.document_date).toLocaleDateString('th-TH'):'—'}</td></tr>})}</tbody></table>{docs.length===0&&<div className="empty">ยังไม่มีหนังสือส่ง</div>}</div></div>{open&&<Modal title="สร้างหนังสือส่ง"onClose={()=>setOpen(false)}><form className="form-grid"onSubmit={submit}><label className="wide">เรื่อง<input required value={form.subject}onChange={e=>setForm({...form,subject:e.target.value})}/></label><label>ผู้รับ<input required value={form.recipient_name}onChange={e=>setForm({...form,recipient_name:e.target.value})}/></label><label>วันที่หนังสือ<input type="date"value={form.document_date}onChange={e=>setForm({...form,document_date:e.target.value})}/></label><label>ช่องทางติดต่อ<input value={form.recipient_contact}onChange={e=>setForm({...form,recipient_contact:e.target.value})}/></label><label>ความเร่งด่วน<select value={form.urgency}onChange={e=>setForm({...form,urgency:e.target.value})}>{Object.entries(urgencyLabel).map(([v,l])=><option key={v} value={v}>{String(l)}</option>)}</select></label><label className="wide">ที่อยู่ผู้รับ<textarea value={form.recipient_address}onChange={e=>setForm({...form,recipient_address:e.target.value})}/></label><div className="form-actions"><button type="button"className="ghost"onClick={()=>setOpen(false)}>ยกเลิก</button><button disabled={busy}>{busy?'กำลังบันทึก…':'บันทึกหนังสือส่ง'}</button></div></form></Modal>}</div>}
function Senders({setError}:{setError:(v:string)=>void}){const[rows,setRows]=React.useState<Sender[]>([]);const[open,setOpen]=React.useState(false);const[form,setForm]=React.useState({organization_name:'',department_name:'',address:'',contact_name:'',contact_phone:'',contact_email:''});async function load(){const{data,error}=await supabase.from('senders').select('id,organization_name,department_name').eq('is_active',true).order('organization_name');if(error)setError(error.message);else setRows(data||[])}React.useEffect(()=>{load()},[]);async function submit(e:React.FormEvent){e.preventDefault();const{error}=await supabase.from('senders').insert({...form,is_active:true});if(error)setError(error.message);else{setOpen(false);setForm({organization_name:'',department_name:'',address:'',contact_name:'',contact_phone:'',contact_email:''});load()}}return <div><div className="toolbar"><div><h1>หน่วยงานผู้ส่ง</h1><p>ข้อมูลหน่วยงานสำหรับทะเบียนหนังสือรับ</p></div><button onClick={()=>setOpen(true)}>+ เพิ่มหน่วยงาน</button></div><div className="panel"><div className="table-wrap"><table><thead><tr><th>หน่วยงาน</th><th>ส่วนงาน</th></tr></thead><tbody>{rows.map(s=><tr key={s.id}><td>{s.organization_name}</td><td>{s.department_name||'—'}</td></tr>)}</tbody></table>{rows.length===0&&<div className="empty">ยังไม่มีหน่วยงานผู้ส่ง</div>}</div></div>{open&&<Modal title="เพิ่มหน่วยงานผู้ส่ง"onClose={()=>setOpen(false)}><form className="form-grid"onSubmit={submit}><label className="wide">ชื่อหน่วยงาน<input required value={form.organization_name}onChange={e=>setForm({...form,organization_name:e.target.value})}/></label><label>ส่วนงาน<input value={form.department_name}onChange={e=>setForm({...form,department_name:e.target.value})}/></label><label>ผู้ติดต่อ<input value={form.contact_name}onChange={e=>setForm({...form,contact_name:e.target.value})}/></label><label>โทรศัพท์<input value={form.contact_phone}onChange={e=>setForm({...form,contact_phone:e.target.value})}/></label><label>อีเมล<input type="email"value={form.contact_email}onChange={e=>setForm({...form,contact_email:e.target.value})}/></label><label className="wide">ที่อยู่<textarea value={form.address}onChange={e=>setForm({...form,address:e.target.value})}/></label><div className="form-actions"><button type="button"className="ghost"onClick={()=>setOpen(false)}>ยกเลิก</button><button>บันทึก</button></div></form></Modal>}</div>}
function Tasks({profile,openDocument}:{profile:Profile|null;openDocument:(id:string)=>void}){const[rows,setRows]=React.useState<any[]>([]);const[filter,setFilter]=React.useState('active');const[loading,setLoading]=React.useState(true);async function load(){if(!profile)return;setLoading(true);let q=supabase.from('document_assignments').select('id,assigned_at,assignment_status,instructions,documents(id,subject,status,urgency)').eq('assignee_id',profile.id).order('assigned_at',{ascending:false});if(filter==='active')q=q.in('assignment_status',['assigned','accepted','in_progress']);if(filter==='done')q=q.eq('assignment_status','completed');const{data,error}=await q;if(error)setRows([]);else setRows(data||[]);setLoading(false)}React.useEffect(()=>{load()},[profile?.id,filter]);return <div><div className="toolbar"><div><h1>งานของฉัน</h1><p>รายการหนังสือที่ได้รับมอบหมายให้ดำเนินการ</p></div><button className="ghost"onClick={load}>รีเฟรช</button></div><div className="panel"><div className="filter-bar"><button className={filter==='active'?'':'ghost'}onClick={()=>setFilter('active')}>งานที่ต้องทำ</button><button className={filter==='done'?'':'ghost'}onClick={()=>setFilter('done')}>เสร็จแล้ว</button></div>{loading?<div className="empty">กำลังโหลด…</div>:<div className="table-wrap"><table><thead><tr><th>เรื่อง</th><th>ความเร่งด่วน</th><th>สถานะหนังสือ</th><th>สถานะงาน</th><th>มอบหมายเมื่อ</th></tr></thead><tbody>{rows.map(x=><tr key={x.id}><td><button className="subject-link"onClick={()=>x.documents?.id&&openDocument(x.documents.id)}>{x.documents?.subject}</button></td><td><span className={'badge urgency '+x.documents?.urgency}>{urgencyLabel[x.documents?.urgency]}</span></td><td>{statusLabel[x.documents?.status]||x.documents?.status}</td><td>{x.assignment_status}</td><td>{new Date(x.assigned_at).toLocaleString('th-TH')}</td></tr>)}</tbody></table>{rows.length===0&&<div className="empty">ไม่มีรายการในมุมมองนี้</div>}</div>}</div></div>}
function Approvals({profile,setError,openDocument}:{profile:Profile|null;setError:(v:string)=>void;openDocument:(id:string)=>void}){const[rows,setRows]=React.useState<any[]>([]);const[busy,setBusy]=React.useState('');async function load(){if(!profile)return;const{data,error}=await supabase.from('approvals').select('id,approval_step,decision,created_at,documents(id,subject,status,urgency)').eq('approver_id',profile.id).eq('decision','pending').order('created_at',{ascending:false});if(error)setError(error.message);else setRows(data||[])}React.useEffect(()=>{load()},[profile?.id]);async function decide(id:string,decision:'approved'|'rejected'|'returned'){setBusy(id);const{error}=await supabase.rpc('decide_approval',{p_approval_id:id,p_decision:decision,p_comment:null});if(error)setError(error.message);else await load();setBusy('')}return <div><div className="toolbar"><div><h1>รายการรออนุมัติ</h1><p>เอกสารที่ถูกส่งมาให้ผู้มีสิทธิ์อนุมัติพิจารณา</p></div><button className="ghost"onClick={load}>รีเฟรช</button></div><div className="panel"><div className="table-wrap"><table><thead><tr><th>เรื่อง</th><th>ความเร่งด่วน</th><th>ขั้นตอน</th><th>วันที่ส่ง</th><th>การดำเนินการ</th></tr></thead><tbody>{rows.map(x=><tr key={x.id}><td><button className="subject-link" onClick={()=>x.documents?.id&&openDocument(x.documents.id)}>{x.documents?.subject}</button></td><td><span className={'badge urgency '+x.documents?.urgency}>{urgencyLabel[x.documents?.urgency]}</span></td><td>{x.approval_step}</td><td>{new Date(x.created_at).toLocaleString('th-TH')}</td><td><div className="row-actions"><button disabled={!!busy}onClick={()=>decide(x.id,'approved')}>{busy===x.id?'กำลังบันทึก…':'อนุมัติ'}</button><button className="ghost"disabled={!!busy}onClick={()=>decide(x.id,'returned')}>ส่งกลับแก้ไข</button><button className="danger-btn"disabled={!!busy}onClick={()=>decide(x.id,'rejected')}>ไม่อนุมัติ</button></div></td></tr>)}</tbody></table>{rows.length===0&&<div className="empty">ไม่มีเอกสารที่รออนุมัติ</div>}</div></div></div>}

function DocumentDetail({documentId,onBack,setError,permissions}:{documentId:string;onBack:()=>void;setError:(v:string)=>void;permissions:string[]}){const[d,setD]=React.useState<any>(null);const[files,setFiles]=React.useState<any[]>([]);const[history,setHistory]=React.useState<any[]>([]);const[assignees,setAssignees]=React.useState<any[]>([]);const[deadlines,setDeadlines]=React.useState<any[]>([]);const[openAssign,setOpenAssign]=React.useState(false);const[uploadBusy,setUploadBusy]=React.useState(false);const[fileInput,setFileInput]=React.useState<HTMLInputElement|null>(null);const[openApproval,setOpenApproval]=React.useState(false);const[busy,setBusy]=React.useState(false);const[statusBusy,setStatusBusy]=React.useState(false);const[openStatus,setOpenStatus]=React.useState(false);const[statusReason,setStatusReason]=React.useState('');const[form,setForm]=React.useState({assignee_id:'',instructions:'',due_at:''});const[approval,setApproval]=React.useState({approver_id:'',step:'1'});async function load(){const[a,b,c,e,f]=await Promise.all([supabase.from('documents').select('*,incoming_document_details(*,senders(*)),outgoing_document_details(*)').eq('id',documentId).single(),supabase.from('document_files').select('id,file_role,version_no,is_current,uploaded_at,google_drive_files(name,mime_type,size_bytes,drive_url)').eq('document_id',documentId).order('uploaded_at',{ascending:false}),supabase.from('document_status_history').select('id,from_status,to_status,changed_at,reason,profiles(full_name)').eq('document_id',documentId).order('changed_at',{ascending:false}),supabase.from('profiles').select('id,full_name,email,employee_code').eq('is_active',true).order('full_name'),supabase.from('deadlines').select('id,assigned_to,due_at,reminder_at,status,profiles(full_name)').eq('document_id',documentId).order('due_at')]);if(a.error)setError(a.error.message);else setD(a.data);if(b.error)setError(b.error.message);else setFiles(b.data||[]);if(c.error)setError(c.error.message);else setHistory(c.data||[]);if(e.error)setError(e.error.message);else setAssignees(e.data||[]);if(f.error)setError(f.error.message);else setDeadlines(f.data||[])}React.useEffect(()=>{load()},[documentId]);async function uploadFile(file:File){setUploadBusy(true);setError('');try{const form=new FormData();form.append('document_id',documentId);form.append('file',file);const{data,error}=await supabase.functions.invoke('drive-upload',{body:form});if(error){let code:string|undefined;if(error instanceof FunctionsHttpError){try{const body=await error.context.json();if(typeof body?.code==='string')code=body.code}catch{}}setError(code?getUploadErrorMessage(code):error instanceof FunctionsFetchError||error instanceof FunctionsRelayError?'เชื่อมต่อบริการอัปโหลดไม่สำเร็จ กรุณาตรวจสอบอินเทอร์เน็ตแล้วลองใหม่':error.message)}else if(!data?.ok)setError(getUploadErrorMessage(data?.code));else await load()}catch{setError('อัปโหลดไฟล์ไม่สำเร็จ กรุณาตรวจสอบการเชื่อมต่อแล้วลองใหม่')}finally{setUploadBusy(false)}}async function assign(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');const{error}=await supabase.rpc('assign_document',{p_document_id:documentId,p_assignee_id:form.assignee_id,p_instructions:form.instructions||null,p_due_at:form.due_at?new Date(form.due_at).toISOString():null});if(error)setError(error.message);else{setOpenAssign(false);setForm({assignee_id:'',instructions:'',due_at:''});await load()}setBusy(false)}async function approve(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');const{error}=await supabase.rpc('create_approval',{p_document_id:documentId,p_approver_id:approval.approver_id,p_approval_step:Number(approval.step)});if(error)setError(error.message);else{setOpenApproval(false);setApproval({approver_id:'',step:'1'});await load()}setBusy(false)}const nextStatus:any=d?.document_type==='outgoing'?{approved:'sent',sent:'archived'}:{approved:'received',received:'registered',assigned:'in_progress',in_progress:'completed',completed:'archived'};const next=nextStatus[d?.status];async function transition(e:React.FormEvent){e.preventDefault();if(!next)return;setStatusBusy(true);setError('');const{error}=await supabase.rpc('update_document_status',{p_document_id:documentId,p_to_status:next,p_reason:statusReason||null});if(error)setError(error.message);else{setOpenStatus(false);setStatusReason('');await load()}setStatusBusy(false)}if(!d)return <div className="empty">กำลังโหลดรายละเอียดเอกสาร…</div>;const inc=d.incoming_document_details?.[0],out=d.outgoing_document_details?.[0];return <div><div className="toolbar"><div><button className="ghost"onClick={onBack}>← กลับรายการ</button><h1>{d.subject}</h1><p>{d.document_type==='incoming'?'หนังสือรับ':'หนังสือส่ง'} · {statusLabel[d.status]||d.status}</p></div><div className="row-actions">{d.status==='draft'&&permissions.includes('document.approve')&&<button className="ghost"onClick={()=>setOpenApproval(true)}>ส่งอนุมัติ</button>}{next&&permissions.includes(next==='archived'?'document.archive':(next==='completed'?'document.complete':'document.update'))&&<button onClick={()=>setOpenStatus(true)}>ถัดไป: {statusLabel[next]}</button>}{d.status==='registered'&&permissions.includes('document.assign')&&<button className="ghost"onClick={()=>setOpenAssign(true)}>มอบหมายงาน</button>}</div></div><section className="workflow-panel"><div className="workflow-title"><b>ขั้นตอนการดำเนินงาน</b><span>สถานะปัจจุบัน: {statusLabel[d.status]||d.status}</span></div><div className="workflow-steps">{(d.document_type==='outgoing'?[['draft','ร่าง'],['pending_approval','รออนุมัติ'],['approved','อนุมัติแล้ว'],['sent','ส่งแล้ว'],['archived','จัดเก็บแล้ว']]:[['draft','ร่าง'],['pending_approval','รออนุมัติ'],['approved','อนุมัติแล้ว'],['received','รับเรื่องแล้ว'],['registered','ลงทะเบียนแล้ว'],['assigned','มอบหมายแล้ว'],['in_progress','กำลังดำเนินการ'],['completed','เสร็จสิ้น'],['archived','จัดเก็บแล้ว']]).map(([v,l],i,a)=><div key={v} className={'workflow-step '+(d.status===v?'current':(a.findIndex((x:any)=>x[0]===d.status)>i?'done':''))}><span>{i+1}</span><small>{l}</small></div>)}</div></section><div className="detail-grid"><section className="panel detail-card"><h2>ข้อมูลเอกสาร</h2><div className="detail-list"><div><b>ความเร่งด่วน</b><span className={'badge urgency '+d.urgency}>{urgencyLabel[d.urgency]}</span></div><div><b>เลขทะเบียน</b><span>{inc?.registered_number||out?.registered_number||'—'}</span></div>{inc&&<><div><b>หน่วยงานผู้ส่ง</b><span>{inc.senders?.organization_name||'—'}</span></div><div><b>เลขที่จากผู้ส่ง</b><span>{inc.external_document_no||'—'}</span></div></>}{out&&<><div><b>ผู้รับ</b><span>{out.recipient_name||'—'}</span></div><div><b>เลขที่หนังสือส่ง</b><span>{out.outgoing_document_no||'—'}</span></div></>}</div></section><section className="panel detail-card"><h2>กำหนดส่งงาน</h2>{deadlines.length===0?<div className="empty">ยังไม่ได้กำหนด Deadline</div>:deadlines.map(x=><div className="timeline-row"key={x.id}><b>{new Date(x.due_at).toLocaleString('th-TH')}</b><span>{x.profiles?.full_name||'—'}</span><small>{x.status} · เตือน {new Date(x.reminder_at).toLocaleString('th-TH')}</small></div>)}</section><section className="panel detail-card"><h2>ไฟล์เอกสาร</h2><div className="upload-row"><input type="file" ref={setFileInput} disabled={uploadBusy}/><button type="button" disabled={uploadBusy} onClick={()=>fileInput?.files?.[0]&&uploadFile(fileInput.files[0])}>{uploadBusy?'กำลังอัปโหลด…':'อัปโหลดเข้า Google Drive'}</button></div>{files.length===0?<div className="empty">ยังไม่มีไฟล์แนบ</div>:files.map(f=><div className="file-row"key={f.id}><div><b>{f.google_drive_files?.name||'ไฟล์'}</b><small>v{f.version_no} · {f.google_drive_files?.mime_type||'ไม่ทราบชนิด'}</small></div>{f.google_drive_files?.drive_url&&<a href={f.google_drive_files.drive_url}target="_blank"rel="noreferrer">เปิดไฟล์</a>}</div>)}</section><section className="panel detail-card wide-card"><h2>ประวัติสถานะ</h2>{history.length===0?<div className="empty">ยังไม่มีประวัติ</div>:history.map(h=><div className="timeline-row"key={h.id}><b>{statusLabel[h.to_status]||h.to_status}</b><span>{h.profiles?.full_name||'ระบบ'}</span><small>{new Date(h.changed_at).toLocaleString('th-TH')}{h.reason?' · '+h.reason:''}</small></div>)}</section></div>{openAssign&&<Modal title="มอบหมายงาน"onClose={()=>setOpenAssign(false)}><form className="form-grid"onSubmit={assign}><label className="wide">ผู้รับผิดชอบ<select required value={form.assignee_id}onChange={e=>setForm({...form,assignee_id:e.target.value})}><option value="">เลือกผู้รับผิดชอบ</option>{assignees.map(x=><option key={x.id}value={x.id}>{x.full_name}{x.employee_code?' — '+x.employee_code:''}</option>)}</select></label><label className="wide">คำสั่ง/รายละเอียดงาน<textarea value={form.instructions}onChange={e=>setForm({...form,instructions:e.target.value})}/></label><label className="wide">กำหนดส่ง<input type="datetime-local"value={form.due_at}onChange={e=>setForm({...form,due_at:e.target.value})}/></label><div className="form-actions"><button type="button"className="ghost"onClick={()=>setOpenAssign(false)}>ยกเลิก</button><button disabled={busy}>{busy?'กำลังบันทึก…':'มอบหมายงาน'}</button></div></form></Modal>}{openApproval&&<Modal title="ส่งเอกสารอนุมัติ"onClose={()=>setOpenApproval(false)}><form className="form-grid"onSubmit={approve}><label className="wide">ผู้อนุมัติ<select required value={approval.approver_id}onChange={e=>setApproval({...approval,approver_id:e.target.value})}><option value="">เลือกผู้อนุมัติ</option>{assignees.map(x=><option key={x.id}value={x.id}>{x.full_name}</option>)}</select></label><label>ลำดับขั้นอนุมัติ<input type="number"min="1"value={approval.step}onChange={e=>setApproval({...approval,step:e.target.value})}/></label><div className="form-actions"><button type="button"className="ghost"onClick={()=>setOpenApproval(false)}>ยกเลิก</button><button disabled={busy}>{busy?'กำลังบันทึก…':'ส่งอนุมัติ'}</button></div></form></Modal>}{openStatus&&<Modal title={'เปลี่ยนสถานะเป็น '+statusLabel[next]}onClose={()=>setOpenStatus(false)}><form className="form-grid"onSubmit={transition}><label className="wide">เหตุผล/หมายเหตุ<textarea value={statusReason}onChange={e=>setStatusReason(e.target.value)} placeholder="ระบุรายละเอียดเพิ่มเติม (ถ้ามี)"/></label><div className="form-actions"><button type="button"className="ghost"onClick={()=>setOpenStatus(false)}>ยกเลิก</button><button disabled={statusBusy}>{statusBusy?'กำลังบันทึก…':'ยืนยันเปลี่ยนสถานะ'}</button></div></form></Modal>}</div>}

function Reports(){const[data,setData]=React.useState<any[]>([]);const[monthly,setMonthly]=React.useState<any[]>([]);React.useEffect(()=>{(async()=>{const[a,b]=await Promise.all([supabase.from('document_report_summary').select('*'),supabase.from('document_monthly_summary').select('*').limit(24)]);setData(a.data||[]);setMonthly(b.data||[])})()},[]);const total=data.reduce((n,x)=>n+Number(x.total_documents),0);const completed=data.filter(x=>x.status==='completed').reduce((n,x)=>n+Number(x.total_documents),0);return <div><div className="toolbar"><div><h1>รายงานและสถิติ</h1><p>สรุปภาพรวมทะเบียนสารบรรณจากฐานข้อมูลโรงเรียน</p></div></div><div className="stats-grid"><div className="stat-card"><b>เอกสารทั้งหมด</b><strong>{total}</strong></div><div className="stat-card"><b>ดำเนินการเสร็จสิ้น</b><strong>{completed}</strong></div><div className="stat-card"><b>เดือนล่าสุด</b><strong>{monthly[0]?.total_documents||0}</strong></div></div><div className="panel"><h2>สรุปรายเดือน</h2><div className="table-wrap"><table><thead><tr><th>เดือน</th><th>ประเภท</th><th>ทั้งหมด</th><th>เสร็จสิ้น</th><th>เร่งด่วน</th></tr></thead><tbody>{monthly.map((x,i)=><tr key={i}><td>{new Date(x.month).toLocaleDateString('th-TH',{year:'numeric',month:'long'})}</td><td>{x.document_type==='incoming'?'หนังสือรับ':'หนังสือส่ง'}</td><td>{x.total_documents}</td><td>{x.completed_documents}</td><td>{x.urgent_documents}</td></tr>)}</tbody></table></div></div></div>}
function DriveHealthCheck({setError}:{setError:(v:string)=>void}){const[busy,setBusy]=React.useState(false);const[result,setResult]=React.useState<any>(null);async function run(){setBusy(true);setResult(null);setError('');const{data,error}=await supabase.functions.invoke('drive-health',{method:'GET'});if(error){if(error instanceof FunctionsHttpError){try{const body=await error.context.json();setResult(body);setError('Google Drive Health Check ไม่ผ่าน: '+(body?.code||error.message));}catch{setError('Google Drive Health Check ไม่ผ่าน: '+error.message)}}else if(error instanceof FunctionsRelayError||error instanceof FunctionsFetchError){setError('เรียก Edge Function ไม่สำเร็จ: '+error.message)}else setError(error.message);setBusy(false);return}setResult(data);if(data?.ok!==true)setError('Google Drive Health Check ไม่ผ่าน: '+(data?.code||'UNKNOWN_ERROR'));setBusy(false)}return <section className="panel drive-health-card"><div className="panel-head"><div><h2>Google Drive — Health Check</h2><p>ทดสอบการเชื่อมต่อ Google Drive ของโรงเรียนผ่าน Supabase Edge Function</p></div><button onClick={run} disabled={busy}>{busy?'กำลังตรวจสอบ…':'ทดสอบ Google Drive'}</button></div>{result&&<div className={'drive-health-result '+(result.ok?'success':'failure')}><div><b>{result.ok?'เชื่อมต่อสำเร็จ':'การตรวจสอบไม่ผ่าน'}</b><span>{result.ok?'Edge Function เข้าถึงโฟลเดอร์หลักของโรงเรียนได้':'ตรวจสอบรายละเอียดข้อผิดพลาดแล้วแก้ไขก่อนเปิดใช้งาน Upload'}</span></div>{result.ok&&<dl><div><dt>Folder</dt><dd>{result.root_folder?.name||'—'}</dd></div><div><dt>Folder ID</dt><dd className="mono">{result.root_folder?.id||'—'}</dd></div><div><dt>Write Test</dt><dd>{result.write_test_performed?'ดำเนินการ':'ไม่ได้เขียนข้อมูล'}</dd></div></dl>}{!result.ok&&<div className="drive-health-code mono">{result.code||'UNKNOWN_ERROR'}</div>}</div>}</section>}
function AuditLogs({setError}:{setError:(v:string)=>void}){const[rows,setRows]=React.useState<any[]>([]);const[q,setQ]=React.useState('');const[loading,setLoading]=React.useState(true);async function load(){setLoading(true);let query=supabase.from('audit_logs').select('id,action,entity_type,entity_id,actor_id,old_data,new_data,created_at,profiles(full_name)').order('created_at',{ascending:false}).limit(100);if(q)query=query.or('action.ilike.%'+q+'%,entity_type.ilike.%'+q+'%');const{data,error}=await query;if(error)setError(error.message);else setRows(data||[]);setLoading(false)}React.useEffect(()=>{load()},[q]);return <div><DriveHealthCheck setError={setError}/><div className="toolbar"><div><h1>ประวัติการใช้งาน</h1><p>ตรวจสอบการเปลี่ยนแปลงสำคัญในระบบ</p></div><button className="ghost" onClick={load}>รีเฟรช</button></div><div className="panel"><div className="filter-bar"><input placeholder="ค้นหาการกระทำหรือประเภทข้อมูล…" value={q} onChange={e=>setQ(e.target.value)}/></div>{loading?<div className="empty">กำลังโหลด…</div>:<div className="table-wrap"><table><thead><tr><th>เวลา</th><th>ผู้ใช้งาน</th><th>การกระทำ</th><th>ข้อมูล</th><th>ID</th></tr></thead><tbody>{rows.map(x=><tr key={x.id}><td>{new Date(x.created_at).toLocaleString('th-TH')}</td><td>{x.profiles?.full_name||'ระบบ'}</td><td><span className="badge">{x.action}</span></td><td>{x.entity_type}</td><td className="mono">{x.entity_id||'—'}</td></tr>)}</tbody></table>{rows.length===0&&<div className="empty">ยังไม่มีประวัติการใช้งานที่เข้าถึงได้</div>}</div>}</div></div>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){return <div className="modal-backdrop"onMouseDown={onClose}><div className="modal"onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><h2>{title}</h2><button className="icon-btn"onClick={onClose}>×</button></div>{children}</div></div>}

class AppErrorBoundary extends React.Component<React.PropsWithChildren, {hasError:boolean; message:string}> {
  state = {hasError:false, message:''};
  static getDerivedStateFromError(error:unknown) {
    return {hasError:true, message:error instanceof Error ? error.message : 'Unexpected application error'};
  }
  componentDidCatch(error:Error, info:React.ErrorInfo) {
    console.error('WBNS e-Document render error', error, info.componentStack);
  }
  render() {
    if (this.state.hasError) return <main style={{minHeight:'100vh',display:'grid',placeItems:'center',padding:24,background:'#f4f7fb',fontFamily:'system-ui,sans-serif',color:'#18324a'}}><section role="alert" style={{maxWidth:560,width:'100%',background:'#fff',padding:28,borderRadius:16,boxShadow:'0 12px 40px #17324a16'}}><div style={{fontWeight:800,color:'#0b4f8a',fontSize:18}}>WBNS e-Document</div><h1 style={{fontSize:22}}>ระบบพบข้อผิดพลาดในการแสดงผล</h1><p>หน้านี้เกิดข้อผิดพลาดระหว่างแสดงผล ข้อมูลในฐานข้อมูลไม่ได้ถูกลบจากเหตุการณ์นี้ โปรดลองโหลดหน้าใหม่ หากยังเกิดซ้ำ โปรดแจ้งผู้ดูแลระบบพร้อมรายละเอียดด้านล่าง</p><details><summary>รายละเอียดข้อผิดพลาด</summary><pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{this.state.message}</pre></details><button onClick={()=>window.location.reload()} style={{marginTop:16}}>โหลดหน้าใหม่</button></section></main>;
    return this.props.children;
  }
}

createRoot(document.getElementById('root')!).render(<React.StrictMode><AppErrorBoundary><App/></AppErrorBoundary></React.StrictMode>);